#!/usr/bin/env python3
"""Pipeline page i18n - script + high-priority template strings."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
P = 'app/pages/dashboard/jobs/[id]/index.vue'

def patch(replacements):
    p = ROOT / P
    text = p.read_text(encoding='utf-8')
    for old, new in replacements:
        if old not in text:
            raise SystemExit(f"MISSING: {old[:100]!r}")
        text = text.replace(old, new, 1)
    p.write_text(text, encoding='utf-8')
    print(f"Patched {P} ({len(replacements)} replacements)")

